const SETS = [
  ['words-4', 'Words 4: family and people', 'Sixteen people words. Several are third declension: the genitive (μητρός, ἀνδρός, παιδός) shows the stem. Learn each noun with its article and genitive, the way a dictionary gives it.', 'Teach the words for mother, father, son and daughter, with their genitives.', 'Ask {him} the Greek for “child” and which English word for a doctor comes from it.', WORDS_4],
  ['words-5', 'Words 5: the city and war', 'The words of Athens at war and at peace: city, people, army, ships, walls, council. Democracy is hiding in here.', 'Explain which two Greek words make “democracy”, and what each means.', 'Ask {him} what a hoplite carried.', WORDS_5],
  ['words-6', 'Words 6: sea, sky and land', 'Odysseus’ world: sea, wind, stars, mountains, islands and storms, plus two verbs for a sea voyage.', 'Explain why ἀφικνέομαι looks passive but is not.', 'Ask {him} which gas is named after the Greek for water.', WORDS_6],
  ['words-7', 'Words 7: gods, temples and heroes', 'Religion ran through Greek life: temples, priests, altars, sacrifices and oracles. And the heroes, half-way between gods and mortals.', 'Explain the difference between θάνατος and ἀθάνατος.', 'Ask {him} what the Oracle at Delphi was, and the Greek word for an oracle.', WORDS_7],
  ['words-8', 'Words 8: home, food and animals', 'Everyday life: doors and tables, bread and wine, cows, sheep and dogs, and the verbs for eating, drinking and sleeping.', 'Explain how the Greek for “dog” gave us the word “cynical”.', 'At dinner, ask {him} the Greek for wine, bread and drink.', WORDS_8],
  ['words-9', 'Words 9: body, mind and feelings', 'Body parts (doctors still use them), and the feelings that drive every myth: fear, anger, hope and love.', 'Pick three medical words and explain the Greek inside each.', 'Ask {him} what an ophthalmologist and a cardiologist look after.', WORDS_9],
  ['words-10', 'Words 10: verbs of action', 'Sixteen verbs that do the work in every story. Many have a strong aorist with a different stem (λαμβάνω → ἔλαβον): learn the two together.', 'Teach four verbs with their aorists.', 'Ask {him} what “eureka” means and who said it.', WORDS_10],
  ['words-11', 'Words 11: more verbs', 'Coming and going, asking and answering, giving and receiving. Watch for the verbs ending -ομαι that are active in meaning.', 'Explain the difference between ἐρωτάω and ἀποκρίνομαι.', 'Ask {him} the Greek for “I give” and which English medical word comes from it.', WORDS_11],
  ['words-12', 'Words 12: adjectives', 'Sixteen describing words: big and small, many and few, easy and heavy. μέγας and πολύς are a little irregular, but you will meet them everywhere.', 'Explain how “oligarchy” and “aristocracy” are built.', 'Ask {him} which English instruments come from βαρύς and ταχύς.', WORDS_12],
  ['words-13', 'Words 13: pronouns and questions', 'The small words that hold sentences together: I, you, we, this, that, who, what, where, when, how and why. Note the question mark ; at the end.', 'Explain the difference between τίς; and τις.', 'Ask {him} questions in Greek: ποῦ; πότε; πῶς;', WORDS_13],
  ['words-14', 'Words 14: numbers', 'Count to ten, then first, second, third, a hundred and a thousand. You already know most of them from maths and sport.', 'Count to ten in Greek and give an English word for each number.', 'Ask {him} what the Greek numbers are inside “decathlon” and “heptathlon”.', WORDS_14],
  ['words-15', 'Words 15: time and adverbs', 'Words for when and how: now, already, always, immediately, again. They are short, they never change their endings, and they are in almost every sentence.', 'Explain the difference between τότε and ἔπειτα.', 'Ask {him} to say “now”, “always” and “immediately” in Greek.', WORDS_15],
  ['words-16', 'Words 16: more prepositions and joining words', 'Nine more prepositions (each with its cases) and the conjunctions that join clauses: since, that, if, as, both… and.', 'Explain the difference between οὐ and μή.', 'Ask {him} to find a Greek preposition hiding in “hypodermic”, “perimeter” and “synthesis”.', WORDS_16],
  ['words-17', 'Words 17: big ideas and third-declension nouns', 'Nature, glory, excellence, contest and judgement: the ideas Greeks argued about. Many are third declension, so learn the genitive with the word.', 'Explain what ἀρετή means and why it is hard to translate with one English word.', 'Ask {him} how “protagonist” and “antagonist” come from ἀγών.', WORDS_17],
];

